package pe.edu.flores.service;
import java.math.*;
import java.time.*;
import java.util.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import pe.edu.flores.dao.*;
import pe.edu.flores.model.Commands.*;
@Service
public class VentaService {
 private final SqlDao db;private final VentaDao dao;private final IdentityService identity;private final FidelizacionService points;private final Clock clock;private final pe.edu.flores.integration.PaymentGateway gateway;
 @Value("${flores.reservation-minutes:5}")int minutes;
 public VentaService(SqlDao db,VentaDao dao,IdentityService identity,FidelizacionService points,Clock clock,pe.edu.flores.integration.PaymentGateway gateway){this.db=db;this.dao=dao;this.identity=identity;this.points=points;this.clock=clock;this.gateway=gateway;}
 public LocalDateTime now(){return LocalDateTime.now(clock);}
 public void sellable(Map<String,Object> trip){if(db.count("SELECT COUNT(*) FROM manifiesto WHERE viaje_id=? AND estado_envio IN ('SIMULADO','ENVIADO')",trip.get("id"))>0)throw new BusinessException("El manifiesto del viaje está cerrado");String state=SqlDao.text(trip,"estado");if(!Set.of("PROGRAMADO","EN_EMBARQUE").contains(state)||!((java.sql.Timestamp)trip.get("salida")).toLocalDateTime().isAfter(now()))throw new BusinessException("El viaje no admite ventas o su hora de salida ya pasó");LocalDate day=((java.sql.Timestamp)trip.get("salida")).toLocalDateTime().toLocalDate();if(!"OPERATIVO".equals(trip.get("bus_estado"))||((java.sql.Date)trip.get("soat_hasta")).toLocalDate().isBefore(day)||((java.sql.Date)trip.get("revision_hasta")).toLocalDate().isBefore(day)||((java.sql.Date)trip.get("licencia_hasta")).toLocalDate().isBefore(day)||!Boolean.TRUE.equals(trip.get("conductor_activo")))throw new BusinessException("Bus o conductor no habilitado para la fecha del viaje");}
 @Transactional public Map<String,Object> reserve(Reserva cmd){var trip=dao.trip(cmd.viajeId());sellable(trip);var r=dao.lockSeat(cmd.viajeId(),cmd.asientoId());if(r.get("boleto_id")!=null)throw new BusinessException("Ese asiento ya está vendido");if(r.get("vence")!=null&&((java.sql.Timestamp)r.get("vence")).toLocalDateTime().isAfter(now())&&!identity.username().equals(r.get("propietario")))throw new BusinessException("Otro usuario mantiene una reserva vigente");String token=UUID.randomUUID().toString();var until=now().plusMinutes(minutes);db.update("UPDATE reserva SET token=?,propietario=?,vence=? WHERE id=?",token,identity.username(),until,r.get("id"));return Map.of("token",token,"vence",until.atZone(clock.getZone()).toOffsetDateTime(),"minutos",minutes);}
 @Transactional public void release(String token){db.update("UPDATE reserva SET token=NULL,propietario=NULL,vence=NULL WHERE token=? AND propietario=? AND boleto_id IS NULL",token,identity.username());}
 @Transactional(readOnly=true)public List<Map<String,Object>> seats(long trip){return dao.seats(trip).stream().map(r->{var out=new LinkedHashMap<>(r);boolean held=r.get("vence")!=null&&((java.sql.Timestamp)r.get("vence")).toLocalDateTime().isAfter(now());out.put("estado",r.get("boleto_id")!=null?"VENDIDO":held?"RESERVADO":"LIBRE");out.put("propia",identity.username().equals(r.get("propietario")));out.remove("propietario");out.remove("boleto_id");return (Map<String,Object>)out;}).toList();}
 @Transactional(readOnly=true)public Map<String,Object> quote(long trip,long passenger,String promo,int redeem){identity.checkPassenger(passenger);var v=dao.trip(trip);sellable(v);return price(v,passenger,promo,redeem);}
 private Map<String,Object> price(Map<String,Object> trip,long passenger,String promo,int redeem){
  db.one("SELECT id FROM pasajero WHERE id=?",passenger);BigDecimal base=SqlDao.money(trip,"precio"),discount=BigDecimal.ZERO;Long promoId=null;
  if(promo!=null&&!promo.isBlank()){var p=db.find("SELECT * FROM promocion WHERE codigo=? AND activo=TRUE AND desde<=? AND hasta>=?",promo.trim().toUpperCase(Locale.ROOT),LocalDate.now(clock),LocalDate.now(clock)).orElseThrow(()->new BusinessException("Promoción inexistente o fuera de vigencia"));promoId=SqlDao.id(p,"id");discount="PORCENTAJE".equals(p.get("tipo"))?base.multiply(SqlDao.money(p,"valor")).divide(new BigDecimal("100"),2,RoundingMode.HALF_UP):SqlDao.money(p,"valor");discount=discount.min(base);}
  var a=points.account(passenger,false);if(redeem<0||redeem>SqlDao.id(a,"saldo"))throw new BusinessException("Saldo de puntos insuficiente");BigDecimal credit=points.pointValue().multiply(BigDecimal.valueOf(redeem));if(credit.compareTo(base.subtract(discount))>0)throw new BusinessException("Los puntos exceden el precio pendiente del pasaje");var result=new LinkedHashMap<String,Object>();result.put("base",base);result.put("descuento",discount);result.put("puntos",redeem);result.put("descuentoPuntos",credit);result.put("total",base.subtract(discount).subtract(credit).setScale(2,RoundingMode.HALF_UP));result.put("promocionId",promoId);return result;
 }
 @Transactional public ResultadoVenta sell(Venta cmd){return sellInternal(cmd,null);}
 private ResultadoVenta sellInternal(Venta cmd,Long previous){
  identity.checkPassenger(cmd.pasajeroId());var trip=dao.trip(cmd.viajeId());sellable(trip);var r=dao.lockSeat(cmd.viajeId(),cmd.asientoId());
  if(r.get("boleto_id")!=null)throw new BusinessException("Ese asiento ya fue vendido");if(!cmd.token().equals(r.get("token"))||!identity.username().equals(r.get("propietario"))||r.get("vence")==null||!((java.sql.Timestamp)r.get("vence")).toLocalDateTime().isAfter(now()))throw new BusinessException("La reserva venció o pertenece a otra sesión. Seleccione el asiento nuevamente");
  var a=points.account(cmd.pasajeroId(),true);var price=price(trip,cmd.pasajeroId(),cmd.promocion(),cmd.puntos());BigDecimal total=(BigDecimal)price.get("total");
  if(!Set.of("EFECTIVO","TARJETA","YAPE","PLIN","PUNTOS").contains(cmd.metodo()))throw new BusinessException("Método de pago no válido");if(!Set.of("VENTANILLA","WEB","APP").contains(cmd.canal()))throw new BusinessException("Canal no válido");if("PUNTOS".equals(cmd.metodo())&&total.signum()!=0)throw new BusinessException("El canje no cubre el precio completo");if(Set.of("TARJETA","YAPE","PLIN").contains(cmd.metodo())&&(cmd.operacion()==null||cmd.operacion().isBlank()))throw new BusinessException("Ingrese el número de operación de demostración");gateway.approve(cmd.metodo(),total,cmd.operacion(),cmd.rechazarPago());
  var u=identity.current();Long employee=u.get("empleado_id")==null?null:((Number)u.get("empleado_id")).longValue();String token=UUID.randomUUID().toString();String code="FH-"+UUID.randomUUID().toString().substring(0,8).toUpperCase(Locale.ROOT);
  long id=db.insert("INSERT INTO boleto(codigo,qr,viaje_id,asiento_id,pasajero_id,empleado_id,promocion_id,canal,precio_base,descuento,puntos_canjeados,precio_final,estado,reprogramado_desde) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,'EMITIDO',?)",code,token,cmd.viajeId(),cmd.asientoId(),cmd.pasajeroId(),employee,price.get("promocionId"),"PASAJERO".equals(u.get("rol"))?"WEB":cmd.canal(),price.get("base"),price.get("descuento"),cmd.puntos(),total,previous);
  db.update("INSERT INTO pago(boleto_id,metodo,monto,operacion,estado,simulado) VALUES(?,?,?,?,'APROBADO',TRUE)",id,cmd.metodo(),total,cmd.operacion()==null?"DEMO-EFECTIVO":cmd.operacion());points.redeem(cmd.pasajeroId(),id,cmd.puntos());db.update("UPDATE reserva SET boleto_id=?,token=NULL,propietario=NULL,vence=NULL WHERE id=?",id,r.get("id"));db.audit(identity.username(),"VENTA",code+"; importe="+total+"; pago simulado");return new ResultadoVenta(id,code,token,total);
 }
 @Transactional public Map<String,Object> cancel(long id){return cancelInternal(id);}
 private Map<String,Object> cancelInternal(long id){var ticket=db.one("SELECT * FROM boleto WHERE id=? FOR UPDATE",id);identity.checkPassenger(SqlDao.id(ticket,"pasajero_id"));if(!"EMITIDO".equals(ticket.get("estado")))throw new BusinessException("Solo se anulan boletos emitidos y sin utilizar");var trip=dao.trip(SqlDao.id(ticket,"viaje_id"));if(!((java.sql.Timestamp)trip.get("salida")).toLocalDateTime().isAfter(now()))throw new BusinessException("No se puede anular después de la salida");if(db.count("SELECT COUNT(*) FROM manifiesto WHERE viaje_id=? AND estado_envio IN ('SIMULADO','ENVIADO')",trip.get("id"))>0)throw new BusinessException("El manifiesto está cerrado para envío");
  db.update("UPDATE boleto SET estado='ANULADO' WHERE id=?",id);db.update("UPDATE pago SET estado='REEMBOLSADO' WHERE boleto_id=?",id);db.update("UPDATE reserva SET boleto_id=NULL,token=NULL,propietario=NULL,vence=NULL WHERE boleto_id=?",id);points.refund(SqlDao.id(ticket,"pasajero_id"),id,((Number)ticket.get("puntos_canjeados")).intValue());db.audit(identity.username(),"ANULACION",ticket.get("codigo")+"; devolución simulada total antes de salida");return Map.of("reembolso",ticket.get("precio_final"),"puntosDevueltos",ticket.get("puntos_canjeados"),"simulado",true);
 }
 @Transactional public Map<String,Object> reprogram(long id,Reprogramacion cmd){var old=db.one("SELECT * FROM boleto WHERE id=? FOR UPDATE",id);if(SqlDao.id(old,"viaje_id")==cmd.viajeId()&&SqlDao.id(old,"asiento_id")==cmd.asientoId())throw new BusinessException("Elija otro viaje o asiento");cancelInternal(id);var n=sellInternal(new Venta(cmd.viajeId(),cmd.asientoId(),SqlDao.id(old,"pasajero_id"),cmd.token(),null,((Number)old.get("puntos_canjeados")).intValue(),cmd.metodo(),cmd.operacion(),SqlDao.text(old,"canal"),false),id);return Map.of("boleto",n,"diferencia",n.total().subtract(SqlDao.money(old,"precio_final")),"nota","Reembolso y nuevo cobro simulados; operación atómica");}
 @Transactional(readOnly=true) public Map<String,Object> ticket(long id){var ticket=dao.ticket(id);identity.checkPassenger(SqlDao.id(ticket,"pasajero_id"));return ticket;}
 @Transactional(readOnly=true) public List<Map<String,Object>> tickets(){var u=identity.current();String where="PASAJERO".equals(u.get("rol"))?" WHERE b.pasajero_id=?":"";Object[] args=where.isEmpty()?new Object[]{}:new Object[]{u.get("pasajero_id")};return db.list("SELECT b.id,b.codigo,b.viaje_id,b.qr,b.estado,b.precio_final,b.canal,b.fecha_emision,p.nombres,p.apellidos,p.documento,a.numero AS asiento,r.origen,r.destino,v.salida FROM boleto b JOIN pasajero p ON p.id=b.pasajero_id JOIN asiento a ON a.id=b.asiento_id JOIN viaje v ON v.id=b.viaje_id JOIN ruta r ON r.id=v.ruta_id"+where+" ORDER BY b.id DESC",args);}
}
